import express from 'express';
import crypto from 'crypto';
import { promisify } from 'util';

const app = express();
app.use(express.json());

const scrypt = promisify(crypto.scrypt);

const SCRYPT_OPTS = { N: 16384, r: 8, p: 1, maxmem: 64 * 1024 * 1024 };

interface VaultEntry {
  encryptedData: Buffer;
  iv: Buffer;
  authTag: Buffer;
  salt: Buffer;
  version: number;
  lockedBy: string | null;
  lockExpiry: number;
}

const vaultStore: Map<string, VaultEntry> = new Map();
const derivedKeys: Map<string, Buffer> = new Map();
const entryMutexes: Map<string, Promise<void>> = new Map();

async function deriveKey(userId: string, passphrase: string, salt: Buffer): Promise<Buffer> {
  // Cache key uses a strong hash of the full passphrase (plus salt), not a truncated slice,
  // to avoid collisions/incorrect key reuse across different passphrases.
  const cacheKey = crypto
    .createHash('sha256')
    .update(userId)
    .update(':')
    .update(salt)
    .update(':')
    .update(passphrase, 'utf8')
    .digest('hex');
  if (derivedKeys.has(cacheKey)) {
    return derivedKeys.get(cacheKey)!;
  }
  const key = await scrypt(passphrase, salt, 32, SCRYPT_OPTS) as Buffer;
  derivedKeys.set(cacheKey, key);
  return key;
}

function encryptPayload(data: string, key: Buffer): { encrypted: Buffer; iv: Buffer; authTag: Buffer } {
  const iv = crypto.randomBytes(16);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  const encrypted = Buffer.concat([cipher.update(data, 'utf8'), cipher.final()]);
  const authTag = cipher.getAuthTag();
  return { encrypted, iv, authTag };
}

function decryptPayload(encrypted: Buffer, key: Buffer, iv: Buffer, authTag: Buffer): string {
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(authTag);
  return decipher.update(encrypted) + decipher.final('utf8');
}

async function withMutex<T>(entryId: string, fn: () => Promise<T>): Promise<T> {
  const prev = entryMutexes.get(entryId) || Promise.resolve();
  let releaseFn: () => void;
  const current = new Promise<void>((resolve) => { releaseFn = resolve; });
  entryMutexes.set(entryId, current);

  await prev;
  try {
    return await fn();
  } finally {
    releaseFn!();
  }
}

app.post('/api/vault/init', async (req, res) => {
  const { userId, passphrase, data } = req.body;
  if (!userId || !passphrase || !data) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  await withMutex(userId, async () => {
    const salt = crypto.randomBytes(16);
    const key = await deriveKey(userId, passphrase, salt);
    const { encrypted, iv, authTag } = encryptPayload(JSON.stringify(data), key);

    vaultStore.set(userId, {
      encryptedData: encrypted,
      iv,
      authTag,
      salt,
      version: 1,
      lockedBy: null,
      lockExpiry: 0
    });

    res.json({ success: true, version: 1 });
  });
});

app.post('/api/vault/update', async (req, res) => {
  const { userId, passphrase, data, expectedVersion } = req.body;
  if (!userId || !passphrase || !data || expectedVersion === undefined) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  await withMutex(userId, async () => {
    const entry = vaultStore.get(userId);
    if (!entry) {
      res.status(404).json({ error: 'Not found' });
      return;
    }

    // Version check BEFORE async operation
    if (entry.version !== expectedVersion) {
      res.status(409).json({ error: 'Version conflict', currentVersion: entry.version });
      return;
    }

    const key = await deriveKey(userId, passphrase, entry.salt);

    // Verify we can decrypt with provided passphrase
    try {
      decryptPayload(entry.encryptedData, key, entry.iv, entry.authTag);
    } catch {
      res.status(403).json({ error: 'Invalid passphrase' });
      return;
    }

    // Re-check version after async key derivation (belt and suspenders)
    if (entry.version !== expectedVersion) {
      res.status(409).json({ error: 'Version conflict', currentVersion: entry.version });
      return;
    }

    const { encrypted, iv, authTag } = encryptPayload(JSON.stringify(data), key);

    entry.encryptedData = encrypted;
    entry.iv = iv;
    entry.authTag = authTag;
    entry.version = expectedVersion + 1;

    res.json({ success: true, version: entry.version });
  });
});

app.post('/api/vault/read', async (req, res) => {
  const { userId, passphrase } = req.body;
  if (!userId || !passphrase) {
    return res.status(400).json({ error: 'Missing fields' });
  }

  await withMutex(userId, async () => {
    const entry = vaultStore.get(userId);
    if (!entry) {
      res.status(404).json({ error: 'Not found' });
      return;
    }

    const key = await deriveKey(userId, passphrase, entry.salt);

    try {
      const decrypted = decryptPayload(entry.encryptedData, key, entry.iv, entry.authTag);
      res.json({ data: JSON.parse(decrypted), version: entry.version });
    } catch {
      res.status(403).json({ error: 'Invalid passphrase' });
    }
  });
});

export default app;
